</sample_inputs>

Here is the source code:
<source_code>
#pragma comment(linker, "/STACK:256000000")

using namespace std;
#include <vector>
#include <iostream>
#include <time.h>
#include <string>
#include <algorithm>
#include <queue>



#define pb push_back
#define mp make_pair
#define X first 
#define Y second
const double EPS = 1E-15;




double mabs(double a)
{
	if (a  < 0)
	return -a;
	else return a;
}

int main()
{
	#ifdef TVISKARON
	freopen("in.txt", "rt", stdin);
	freopen("out.txt", "wt", stdout);
	#else
	//freopen("input.txt", "rt", stdin);
	//freopen("output.txt", "wt", stdout);
	#endif
	int x, y, n;
	cin >>  x >> y >> n;


	int a, b;
	double ans = 100000000;
	double d = double((x + .0)) / y;
	for(int j = 1; j <= n; j++)
	{
		int l = 0, r = 1000 * 1000 * 1000;
		while(r - l > 10)
		{
		int m1 = l + (r - l) / 3;
		int m2 = r - (r - l) / 3;
		double t1 = mabs(d - (m1 + .0) / j);
		double t2 = mabs(d - (m2 + .0) / j);
		//cout << t1 <<  ' ' << t2 << endl;
		if (t1 > t2)
			l = m1;
		else r = m2;
		}
		for(int i = l; i <= r + 3; i++)
		{
			double v = mabs(d - (i + .0) / j);
			if (ans - EPS > v)
			{
				ans = v;
				a = i;
				b = j;
			}
		}
	}
	std::cout  << a << '/' << b;
}
</source_code>
